fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as stated in the problem): start + sub.len() <= main.len()
    // We implement the exact element-wise comparison under that assumption.
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty sub always qualifies.
    if sub.is_empty() {
        return true;
    }

    // If sub is longer than main, it cannot be a contiguous subarray.
    if sub.len() > main.len() {
        return false;
    }

    // Search all valid starting indices k where sub could fit in main.
    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}